public class BankAccount
{
    private decimal balance;   // hidden from outside
    public decimal Balance      // anyone can read
    {
        get { return balance; }
    }
}

public class Animal
{
    protected string Name;
}

public class Dog : Animal
{
    public void Bark()
    {
        Console.WriteLine(Name); // OK - protected
    }
}

var d = new Dog();
// d.Name = "Rex";  // ERROR - protected!

internal class Helper
{
    internal void DoWork() { }
}

// Same assembly:
var h = new Helper();
h.DoWork();  // OK

// Different assembly: ERROR

