slides.example:
public class Base
{
    protected internal int Value1;
    private protected int Value2;
}

// In same assembly:
class Derived : Base
{
    void Test() {
        var v1 = Value1;  // OK - same assembly
        var v2 = Value2;  // OK - derived + same assembly
    }
}

class MyType      // defaults to internal
{
    int MyField;    // defaults to private

    void MyMethod() // defaults to private
    {
    }
}

public class Animal
{
    public void Eat() { }
    protected void Sleep() { }
    private void Think() { }
}

public class Cat : Animal
{
    public void Life()
    {
        Eat();    // OK
        Sleep();  // OK
        // Think(); // ERROR - private!
    }
}

